/** Local browser persistence only. A file export is a separate safety copy. */
export function saveHealthView(health, available = health.available, { unknownTimeLabel = '' } = {}) {
  const failed = health.status === 'unsaved' || health.status === 'conflict';
  const label = failed ? 'Not saved — export needed' : health.status === 'stale' ? 'Saved copy changed in another tab' : health.status === 'pending' ? 'Saving in this browser…' : !available ? 'Browser saves unavailable' : health.hasState ? 'Saved in this browser' : 'No life saved yet';
  const lastSaved = health.lastSavedAt ? `Last saved: ${new Date(health.lastSavedAt).toLocaleString(undefined, { timeZoneName: 'short' })}` : health.hasDurableState ? unknownTimeLabel || 'Last saved: time not recorded in this older save.' : health.hasState ? 'No successful browser save yet.' : '';
  const problem = health.status === 'conflict' ? 'Saving is paused because this slot changed in another tab. Export the latest session before reloading.' : health.status === 'stale' ? 'This tab has an older saved copy, not new unsaved choices. Reload the saved-life list before continuing.' : !available ? `Browser storage is unavailable. ${health.hasState ? 'Export your life to keep progress.' : 'New lives will need a file export to keep them.'}` : health.status === 'unsaved' ? 'The latest choices have not reached browser storage. Export them before closing this page.' : '';
  return { label, lastSaved, problem, warning: failed || health.status === 'stale' || !available, exportable: health.hasState && (failed || health.status === 'stale' || !available) };
}
export function renderSaveHealth(health, { e, available = health.available, live = false, id = '', exportButton = true, unknownTimeLabel = '' }) {
  const view = saveHealthView(health, available, { unknownTimeLabel });
  return `<div class="save-health ${view.warning ? 'save-health-warning' : ''}" data-save-health data-save-slot="${health.id}" data-save-live="${live}" data-save-state="${health.status}" data-save-at="${e(health.lastSavedAt || '')}" ${unknownTimeLabel ? `data-save-unknown-time="${e(unknownTimeLabel)}"` : ''} role="group" aria-label="Browser save status for slot ${health.id + 1}"><div class="save-health-copy"><span data-save-label>${e(view.label)}</span><small data-save-time ${view.lastSaved ? '' : 'hidden'}>${e(view.lastSaved)}</small><span ${id ? `id="${e(id)}"` : ''} class="${view.problem ? '' : 'sr-only'}" data-save-problem role="status" aria-live="polite" aria-atomic="true">${e(view.problem)}</span></div>${exportButton ? `<button class="button secondary small" type="button" data-op="export-session" data-id="${health.id}" aria-label="Export latest session from slot ${health.id + 1}" ${view.exportable ? '' : 'hidden'}>Export latest session</button>` : ''}</div>`;
}
